typedef struct filter { struct filter *next; void *ctx;
    int (*run)(struct filter *f, request *r, response *resp); } filter;

int chain_run(filter *f, request *r, response *resp) {
    if (!f) return target_handle(r, resp);     /* target */
    return f->run(f, r, resp);                 /* filter delegates to f->next */
}
